type RestaurantListItemProps = ComponentProps<typeof RestaurantListItem>;

type StoryArgs = RestaurantListItemProps & {
  groupHeadline: string;
};

/** Strips the story-only controls so only component props reach the card. */
const toItemProps = ({ groupHeadline: _groupHeadline, ...args }: StoryArgs): RestaurantListItemProps => args;

/** Renders the items the same way core does (see restaurant-list-renderer): one group inside a
 * BaseListGroupRenderer, so the card gets the block padding, the responsive grid and the cell it
 * stretches into, and the wait-time label that hangs above the card lands in the gap the list leaves.
 * The group headline comes from the story args; `items` defaults to the single item the args describe. */
const InListGroup = ({
  args,
  items = [toItemProps(args)],
}: {
  args: StoryArgs;
  items?: Array<RestaurantListItemProps>;
}) => (
  <BaseListGroupRenderer
    data={[
      {
        id: "story-group",
        headline: args.groupHeadline,
        isExpanded: true,
        listObjects: items.map((item, index) => ({ ...item, id: `item-${index}` })),
      },
    ]}
    isExpandableList={false}
    renderItem={({ id, ...item }) => <RestaurantListItem key={id} {...item} />}
  />
);

