export const LongQueueModal: Story = {
  args: {
    shouldShowWarningModal: true,
    labels: { ...labels, waitTimeLabel: "30-40 min väntetid" },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // While blocked the whole card is a button that opens the modal instead of following the link.
    await userEvent.click(canvas.getByRole("button", { name: /Kvachos/ }));

    // Presence, not visibility: the modal fades in via the 300ms modal-opacity CSS animation and
    // Chromatic pauses CSS animations, so an ancestor can still compute to opacity 0 here.
    // A soft block still lets the visitor continue to the restaurant.
    await expect(await canvas.findByText("Lång kö")).toBeInTheDocument();
    await expect(canvas.getByText("30-40 min väntetid")).toBeInTheDocument();
    await expect(canvas.getByRole("link", { name: "Vidare till restaurangen" })).toBeInTheDocument();
  },
};

export const FullQueueModal: Story = {
  args: {
    shouldShowBlockingModal: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole("button", { name: /Kvachos/ }));

    // Presence, not visibility - see the note in LongQueueModal.
    // A hard block replaces the wait time with the full-queue text and drops the continue link.
    await expect(await canvas.findByText("Kön är full")).toBeInTheDocument();
    await expect(canvas.getByText(labels.restaurantWaitTimePaused)).toBeInTheDocument();
    await expect(canvas.queryByRole("link", { name: "Vidare till restaurangen" })).not.toBeInTheDocument();
  },
};
